/**
 * Types for the JSON files in src/data. Every file is generated by tools/build-data.mjs, so these types
 * describe what the pipeline writes; if a tool's output changes shape, the type check catches it.
 */

/** One method pulled from the source, with its doc comment. */
export interface MethodSource {
  /** Path from the repo root, such as "EmergentSociety.Core/Systems/ReproductionSystem.cs". */
  file: string;
  name: string;
  /** First line (the doc comment) and last line, 1-based, in the file the page was built from. */
  start: number;
  end: number;
  code: string[];
}

/** A line to highlight, found by its text inside a method. */
export interface Anchor {
  method: string;
  line: number;
}

/** The doc comment and class default of one setting. */
export interface SettingDoc {
  doc: string;
  line: number;
  /** The default written in SimulationSettings, such as "0.7f", or null when it has none. */
  classDefault: string | null;
}

/** One public member of Entity, with its doc comment. */
export interface EntityMember {
  name: string;
  type: string;
  line: number;
  doc: string;
}

/** code.json: everything the site shows from the source. */
export interface CodeData {
  methods: Record<string, MethodSource>;
  anchors: Record<string, Anchor>;
  settings: Record<string, SettingDoc>;
  entity: EntityMember[];
  /** Test file name to the test methods it declares. */
  tests: Record<string, { name: string; line: number }[]>;
}

/** tests.json: one entry per test method. */
export interface TestResult {
  cls: string;
  name: string;
  cases: number;
  passed: boolean;
  error: string | null;
}

/** One reproduction check: a ready pair with one condition changed, run through the real ReproductionSystem. */
export interface ReproductionCheck {
  key: string;
  conceived: boolean;
  femaleEnergyAfter: number;
  partnerEnergyAfter: number;
  dueTick: number | null;
}

/** What LineageRegistry answered about Ada and one male relative. */
export interface KinshipRow {
  key: string;
  id: number;
  closeKin: boolean;
  cousins: boolean;
  auntOrUncle: boolean;
  distantKin: boolean;
}

/** How often the real ReproductionSystem conceived for one kind of pair. */
export interface MeasuredChance {
  trials: number;
  conceived: number;
  share: number;
}

/** rules.json: baseline settings plus single-rule checks. */
export interface RulesData {
  settings: Record<string, number | boolean>;
  checks: ReproductionCheck[];
  kinship: KinshipRow[];
  chances: Record<'unrelated' | 'cousins' | 'uncleNiece', MeasuredChance>;
}

/** One entity in a meeting frame. */
export interface MeetingEntity {
  id: number;
  sex: 'Female' | 'Male';
  x: number;
  y: number;
  energy: number;
  age: number;
  pregnant: boolean;
  dueTick: number | null;
  lastBirth: number | null;
}

/** The state of the meeting scene after one tick. The first frame is the start. */
export interface MeetingFrame {
  /** The simulation's tick count after this frame's step; the step that ran was tick - 1. */
  tick: number;
  relationship: number;
  food: number[];
  entities: MeetingEntity[];
}

/** meeting.json: two founders recorded through the real Simulation. */
export interface MeetingData {
  seed: number;
  width: number;
  height: number;
  capacity: number[];
  /** Frame tick at which the pair could mate but the conception roll failed. */
  missedAt: number | null;
  conceivedAt: number;
  bornAt: number;
  frames: MeetingFrame[];
}

/** Totals at the end of a recorded seed, read from the simulation's own statistics. */
export interface SeedStats {
  alive: number;
  births: number;
  starved: number;
  cold: number;
  killed: number;
  oldAge: number;
  pregnanciesLost: number;
  cellsBuilt: number;
  groups: number;
}

/** A seed file as written by tools/trace/SeedRecorder.cs. The packed format is described there. */
export interface SeedRecord {
  seed: number;
  width: number;
  height: number;
  ticks: number;
  foodStep: number;
  foodMax: number;
  foodBytes: number;
  entityCount: number;
  trees: [number, number][];
  /** Natural shelter cells, as y * width + x. */
  natural: number[];
  /** Built shelter cells: [cell, first frame, last frame]. */
  built: [number, number, number][];
  /** Killings: [frame, cell]. */
  killings: [number, number][];
  stats: SeedStats;
  /** Base64 of the packed food keyframes and entity tracks. */
  data: string;
}

/** One entity in a world frame. */
export interface WorldEntity {
  /** Order of first appearance in the recording, starting at 1. */
  id: number;
  female: boolean;
  x: number;
  y: number;
  pregnant: boolean;
  wood: boolean;
  /** Younger than the maturity age. */
  child: boolean;
}

/** The world after one tick (frame 0 is the start). */
export interface WorldFrame {
  tick: number;
  /** Food per cell, row by row. */
  food: Float32Array;
  /** Every shelter cell, natural and built, as y * width + x. */
  shelterCells: number[];
  entities: WorldEntity[];
  /** Cells where someone was killed this tick. */
  kills: number[];
  /** Births and deaths since the start, up to this frame. */
  born: number;
  died: { killed: number; cold: number; starved: number; oldAge: number };
}

/** A decoded seed, ready to draw. */
export interface WorldData {
  seed: number;
  width: number;
  height: number;
  ticks: number;
  foodMax: number;
  trees: [number, number][];
  natural: number[];
  stats: SeedStats;
  frames: WorldFrame[];
}

/** One line of code that proves a link exists. */
export interface Evidence {
  file: string;
  line: number;
  text: string;
}

/** A link in the systems map. writes: system to state. reads: state to system. guides: system to system. */
export interface MapEdge {
  from: string;
  to: string;
  kind: 'writes' | 'reads' | 'guides';
  evidence: Evidence[];
}

export interface MapSystem {
  key: string;
  label: string;
  phase: number;
  desc: string;
  files: string[];
  tests: string[];
  reads: string[];
  writes: string[];
  /** Systems that ask this one for a decision. */
  guides: string[];
}

export interface MapState {
  key: string;
  label: string;
  group: string;
  desc: string;
}

export interface MapLoop {
  title: string;
  story: string;
  hops: [string, string][];
}

/** systems.json: the scanned systems map. */
export interface SystemsData {
  phases: string[];
  systems: MapSystem[];
  state: MapState[];
  edges: MapEdge[];
  loops: MapLoop[];
}

/** build.json: when the data was generated and from which commit. */
export interface BuildData {
  builtAt: string;
  commit: { hash: string; message: string } | null;
  uncommittedCore: boolean | null;
}
